class Solution:
    def matrixBlockSum(self, matrix: List[List[int]], k: int) -> List[List[int]]:
        ROWS, COLS = len(matrix), len(matrix[0])

        prefix_sums = [[0] * (COLS + 1) for _ in range(ROWS + 1)]

        for r in range(1, ROWS + 1):
            for c in range(1, COLS + 1):
                prefix_sums[r][c] = prefix_sums[r - 1][c] + prefix_sums[r][c - 1] + \
                    matrix[r - 1][c - 1] - prefix_sums[r - 1][c - 1]

        res = [[0] * COLS for _ in range(ROWS)]
        for r in range(ROWS):
            for c in range(COLS):
                res[r][c] = prefix_sums[min(r + k + 1, ROWS)][min(c + k + 1, COLS)] - \
                    prefix_sums[max(r - k, 0)][min(c + k + 1, COLS)] - \
                    prefix_sums[min(r + k + 1, ROWS)][max(c - k, 0)] + \
                    prefix_sums[max(r - k, 0)][max(c - k, 0)]

        return res

class Solution:
    def matrixBlockSum(self, mat, K):
        m, n = len(mat), len(mat[0])
        accu = [[0 for _ in range(n+1)] for _ in range(m+1)]
        for i in range(m):
            for j in range(n):
                accu[i+1][j+1] = accu[i+1][j]+accu[i][j+1]-accu[i][j]+mat[i][j]
        result = [[0 for _ in range(n)] for _ in range(m)]        
        for i in range(m):
            for j in range(n):
                r1, c1, r2, c2 = max(i-K, 0), max(j-K, 0), min(i+K+1, m), min(j+K+1, n)
                result[i][j] = accu[r2][c2]-accu[r1][c2]-accu[r2][c1]+accu[r1][c1]
        return result

class Solution:
    def distinctEchoSubstrings(self, s: str) -> int:
        hash=set()
        n=len(s)
        for i in range(n):
            for j in range(i):

                if (i-j)&1==1:

                    k=(i-j)//2

                    if s[j:j+k+1]==s[j+k+1:i+1]:
                        hash.add(s[j:j+k+1]+s[j+k+1:i+1])
        return len(hash)

class Solution:
    def distinctEchoSubstrings(self, text):
        result = set()
        for l in range(1, len(text)//2+1):
            count = sum(text[i] == text[i+l] for i in range(l))
            for i in range(len(text)-2*l):
                if count == l:
                    result.add(text[i:i+l])
                count += (text[i+l] == text[i+l+l]) - (text[i] == text[i+l])
            if count == l:
                result.add(text[len(text)-2*l:len(text)-2*l+l])
        return len(result)

class Solution:
    def distinctEchoSubstrings(self, text):
        MOD = 10**9+7
        D = 27  # a-z and ''
        result = set()
        for i in range(len(text)-1):
            left, right, pow_D = 0, 0, 1
            for l in range(1, min(i+2, len(text)-i)):
                left = (D*left + (ord(text[i-l+1])-ord('a')+1)) % MOD
                right = (pow_D*(ord(text[i+l])-ord('a')+1) + right) % MOD
                if left == right:  # assumed no collision
                    result.add(left)
                pow_D = (pow_D*D) % MOD 
        return len(result)

class Solution:
    def distinctEchoSubstrings(self, text):
        def compare(text, l, s1, s2):
            for i in range(l):
                if text[s1+i] != text[s2+i]:
                    return False
            return True

        MOD = 10**9+7
        D = 27  # a-z and ''
        result = set()
        for i in range(len(text)):
            left, right, pow_D = 0, 0, 1
            for l in range(1, min(i+2, len(text)-i)):
                left = (D*left + (ord(text[i-l+1])-ord('a')+1)) % MOD
                right = (pow_D*(ord(text[i+l])-ord('a')+1) + right) % MOD
                if left == right and compare(text, l, i-l+1, i+1):
                    result.add(text[i+1:i+1+l])
                pow_D = (pow_D*D) % MOD 
        return len(result)

class Solution:
    def distinctEchoSubstrings(self, text):
        def KMP(text, l, result):
            prefix = [-1]*(len(text)-l)
            j = -1
            for i in range(1, len(prefix)):
                while j > -1 and text[l+j+1] != text[l+i]:
                    j = prefix[j]
                if text[l+j+1] == text[l+i]:
                    j += 1
                prefix[i] = j
                if (j+1) and (i+1) % ((i+1) - (j+1)) == 0 and \
                   (i+1) // ((i+1) - (j+1)) % 2 == 0:
                    result.add(text[l:l+i+1])
            return len(prefix)-(prefix[-1]+1) \
                   if prefix[-1]+1 and len(prefix) % (len(prefix)-(prefix[-1]+1)) == 0 \
                   else float("inf")

        result = set()
        i, l = 0, len(text)-1
        while i < l:  # aaaaaaaaaaaaaaaaaaaaaaaaaaaaaabcdefabcdefabcdef
            l = min(l, i + KMP(text, i, result))
            i += 1
        return len(result)

